contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        // First, call Initialized on the fresh contract.
        bool reverted1;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        // Then, try to call SetMinSum. It must revert because the contract is initialized.
        bool reverted2;
        c.SetMinSum(_val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        // General rule: Initialized never reverts, and it makes a subsequent SetMinSum revert.
        assert(!reverted1 && reverted2);
    }
}

